package com.yihe.framework.ehr;
import org.springframework.web.bind.annotation.*;import javax.servlet.http.*;import java.util.*;import com.fasterxml.jackson.databind.ObjectMapper;import static com.yihe.framework.ehr.EhrAccess.*;import static com.yihe.framework.ehr.EhrController.ok;
@RestController @RequestMapping("/ehr/api/ai-tools")
public class AiToolManagementApi {
 private final EhrAccess access;private final AiToolSettings settings;private final HealthAgentTools tools;private final EhrRepository db;private final ObjectMapper json=new ObjectMapper();
 public AiToolManagementApi(EhrAccess a,AiToolSettings s,HealthAgentTools t,EhrRepository d){access=a;settings=s;tools=t;db=d;}
 @ModelAttribute public void headers(HttpServletResponse r){r.setHeader("Cache-Control","private, no-store");}
 private void check(boolean b,String msg){if(!b)throw new EhrException(422,msg);}private String s(Object v){return v==null?"":String.valueOf(v);}private void manage(EhrActor a){if(!a.doctor||a.mobile)throw new EhrException(403,"仅医生管理端可配置或测试工具");}
 @SuppressWarnings("unchecked") private List<Map<String,Object>> rows(Object value,int max){check(value instanceof List&&((List<?>)value).size()<=max,"工具列表无效或超过限制");for(Object x:(List<?>)value)check(x instanceof Map,"工具记录无效");return (List<Map<String,Object>>)value;}
 static final String[][] BUILTINS={{"search_employees","搜索职工档案","data"},{"get_employee_record","查询职工健康档案","data"},{"list_exam_reports","查询体检报告目录","reports"},{"get_exam_report","读取体检报告明细","reports"},{"get_health_statistics","获取人群健康统计","analysis"},{"get_digital_worker_overview","数字员工任务概览","system"},{"list_digital_worker_tasks","查询数字员工任务","system"},{"find_abnormal_results","查询异常检查项目","analysis"},{"prepare_employee_delete","生成职工删除确认预览","system"},{"prepare_employee_update","生成职工资料变更预览","system"}};
 static final String[][] EXAMPLES={{"generate_intervention","生成干预方案草稿","plans"},{"send_followup_msg","发送随访提醒","messages"},{"ocr_health_report","体检报告OCR识别","data"},{"analyze_trend","健康趋势分析","analysis"},{"evaluate_risk","评估健康风险等级","analysis"},{"generate_report","生成评估报告","reports"},{"create_followup_plan","创建随访计划","plans"},{"update_intervention","更新干预执行状态","plans"}};
 private String[] builtin(String f){for(String[] x:BUILTINS)if(x[0].equals(f))return x;return null;}
 @SuppressWarnings("unchecked") private List<Map<String,Object>> catalog(EhrActor a,Map<String,Object> state){Map<String,Map<String,Object>> specs=new LinkedHashMap<>();for(Object obj:tools.catalog(true)){Map<String,Object> m=(Map<String,Object>)obj;specs.put(s(m.get("name")),m);}Map<String,Map<String,Object>> saved=new LinkedHashMap<>();for(Map<String,Object> row:rows(state.get("tools"),100))saved.put(s(row.get("function")),row);List<Map<String,Object>> out=new ArrayList<>();for(String[] x:BUILTINS){Map<String,Object> spec=specs.get(x[0]);if(spec==null)continue;boolean write=x[0].startsWith("prepare_"),doctorOnly=write||x[0].contains("digital_worker");Map<String,Object> row=map("id",x[0],"function",x[0],"name",x[1],"category",x[2],"description",spec.get("description"),"schema",spec.get("parameters"),"roles",doctorOnly?Arrays.asList("doctor"):Arrays.asList("doctor","member"),"confirmation",write?"always":"auto","conditions",Arrays.asList("highRisk","medical"),"enabled",true,"bound",true,"write",write,"simulated",false,"source","真实来源：HealthAgentTools现有处理器");if(saved.containsKey(x[0]))row.putAll(saved.remove(x[0]));row.put("bound",true);row.put("schema",spec.get("parameters"));row.put("write",write);row.put("simulated",false);row.put("source","真实来源：HealthAgentTools现有处理器");out.add(row);}for(String[] x:EXAMPLES){Map<String,Object> row=map("id",x[0],"function",x[0],"name",x[1],"category",x[2],"description","待接入对应业务处理器。当前仅维护配置、校验参数，不执行业务操作。","schema",map("type","object","properties",map(),"required",new ArrayList<>(),"additionalProperties",false),"roles",Arrays.asList("doctor"),"confirmation","always","conditions",Arrays.asList("highRisk","medical"),"enabled",false,"bound",false,"write",true,"simulated",true,"source","模拟数据来源：用户参考图；未接入处理器");if(saved.containsKey(x[0]))row.putAll(saved.remove(x[0]));row.put("bound",false);row.put("enabled",false);row.put("simulated",true);row.put("write",true);row.put("source","模拟数据来源：用户参考图；未接入处理器");out.add(row);}for(Map<String,Object> m:saved.values()){Map<String,Object> row=new LinkedHashMap<>(m);row.put("bound",false);row.put("enabled",false);row.put("simulated",false);row.put("write",true);row.put("source","本组织登记的工具定义；未接入处理器");out.add(row);}return out;}
 private Map<String,Object> view(EhrActor a,Map<String,Object> state){Map<String,Object> out=new LinkedHashMap<>(state);out.put("tools",catalog(a,state));out.put("canManage",a.doctor&&!a.mobile);return out;}
 @GetMapping public Object get(HttpServletRequest r){EhrActor a=access.web(r);return ok(view(a,settings.read(a)));}
 @PutMapping public Object save(HttpServletRequest r,@RequestBody Map<String,Object> body){EhrActor a=access.web(r);manage(a);synchronized(settings){Map<String,Object> old=settings.read(a);if(EhrService.num(old.get("version"))!=EhrService.num(body.get("version")))throw new EhrException(409,"工具配置已更新，请刷新后重试");List<Map<String,Object>> input=rows(body.get("tools"),100),categories=rows(body.get("categories"),50),clean=new ArrayList<>();Set<String> ids=new HashSet<>(),cats=new HashSet<>(Arrays.asList("data","analysis","plans","messages","reports","system"));for(Map<String,Object> c:categories){check(s(c.get("id")).matches("[A-Za-z0-9_-]{1,64}")&&!cats.contains(s(c.get("id")))&&!s(c.get("name")).trim().isEmpty()&&s(c.get("name")).length()<=100,"分类名称或标识无效");cats.add(s(c.get("id")));}for(Map<String,Object> m:input){String f=s(m.get("function"));check(f.matches("[a-z][a-z0-9_]{1,63}")&&ids.add(f),"工具标识无效或重复");check(!s(m.get("name")).trim().isEmpty()&&s(m.get("name")).length()<=150&&s(m.get("description")).length()<=2000,"工具名称或说明无效");check(cats.contains(s(m.get("category"))),"工具分类不存在");check(m.get("roles") instanceof List&&((List<?>)m.get("roles")).size()<=2,"调用角色无效");for(Object role:(List<?>)m.get("roles"))check(Arrays.asList("doctor","member").contains(role),"调用角色无效");String confirmation=s(m.get("confirmation"));check(Arrays.asList("auto","always","conditional").contains(confirmation),"确认策略无效");check(m.get("conditions") instanceof List&&((List<?>)m.get("conditions")).size()<=3,"确认条件无效");for(Object condition:(List<?>)m.get("conditions"))check(Arrays.asList("highRisk","medical","special").contains(condition),"确认条件无效");check(!confirmation.equals("conditional")||!((List<?>)m.get("conditions")).isEmpty(),"条件确认至少选择一项条件");boolean bound=builtin(f)!=null,write=f.startsWith("prepare_");check(!write||confirmation.equals("always"),"资料变更和删除必须保留原人工确认流程");check(!(write||f.contains("digital_worker"))||!((List<?>)m.get("roles")).contains("member"),"此工具仅开放医生管理端");check(bound||!Boolean.TRUE.equals(m.get("enabled")),"未接入处理器的工具不能启用");Object schema=m.get("schema");if(!bound){check(schema instanceof Map,"参数定义须为JSON Schema对象");Map<?,?> sc=(Map<?,?>)schema;check("object".equals(sc.get("type"))&&sc.get("properties") instanceof Map&&sc.get("required") instanceof List,"参数定义需包含object类型、properties和required");check(jsonSize(schema)<=20000,"参数定义过大");}clean.add(map("id",f,"function",f,"name",m.get("name"),"description",m.get("description"),"category",m.get("category"),"roles",m.get("roles"),"confirmation",confirmation,"conditions",m.get("conditions"),"enabled",Boolean.TRUE.equals(m.get("enabled")),"schema",schema));}for(String[] b:BUILTINS)check(ids.contains(b[0]),"内置工具不能删除，请使用停用");Map<String,Object> next=map("version",EhrService.num(old.get("version"))+1,"tools",clean,"categories",categories,"tests",old.get("tests"));settings.write(a,next);return ok(view(a,next));}}
 private int jsonSize(Object v){try{return json.writeValueAsBytes(v).length;}catch(Exception e){throw new EhrException(422,"JSON格式无效");}}
 @PostMapping("/test") @SuppressWarnings("unchecked") public Object test(HttpServletRequest req,@RequestBody Map<String,Object> b){EhrActor a=access.web(req);manage(a);String f=s(b.get("function"));Map<String,Object> selected=null;for(Map<String,Object> row:catalog(a,settings.read(a)))if(f.equals(row.get("function")))selected=row;check(selected!=null,"工具不存在");check(b.get("arguments") instanceof Map&&jsonSize(b.get("arguments"))<=20000,"参数须为不超过20KB的JSON对象");Map<String,Object> args=(Map<String,Object>)b.get("arguments");boolean bound=Boolean.TRUE.equals(selected.get("bound")),write=Boolean.TRUE.equals(selected.get("write")),success=false,executed=false;String message;Object result=null;long started=System.currentTimeMillis();try{if(!bound){message="工具尚未接入业务处理器，未执行；仅检查JSON参数格式。";}else{tools.validate(f,args,true);settings.enforce(a,f,Boolean.TRUE.equals(b.get("confirmed")));if(write){message="参数校验通过；本次未生成变更或删除预览，实际操作请到数字健康师发起并人工确认。";success=true;}else{result=tools.executeConfirmed(a,"","","工具管理测试","",f,args,new ArrayList<>(),Boolean.TRUE.equals(b.get("confirmed")));check(jsonSize(result)<=100000,"查询结果过大，请缩小范围");success=true;executed=true;message="已执行真实只读查询，未修改职工资料。";}}}catch(EhrException ex){message=ex.getMessage();}catch(Exception ex){message="工具执行未完成，请核对参数或检查服务日志。";}Map<String,Object> record=map("id",UUID.randomUUID().toString(),"function",f,"name",selected.get("name"),"success",success,"executed",executed,"message",message,"durationMs",System.currentTimeMillis()-started,"createdAt",now()+"Z","actor",a.user);int version;Map<String,Object> configuration;synchronized(settings){Map<String,Object> state=settings.read(a);List<Map<String,Object>> tests=new ArrayList<>(rows(state.get("tests"),200));tests.add(record);if(tests.size()>100)tests=new ArrayList<>(tests.subList(tests.size()-100,tests.size()));state.put("tests",tests);version=EhrService.num(state.get("version"))+1;state.put("version",version);settings.write(a,state);configuration=view(a,state);}return ok(map("record",record,"result",result,"version",version,"configuration",configuration));}
 @GetMapping("/logs") public Object logs(HttpServletRequest req,@RequestParam(defaultValue="1") int page,@RequestParam(defaultValue="10") int limit,@RequestParam(defaultValue="") String query){EhrActor a=access.web(req);manage(a);check(page>=1&&page<=10000&&limit>=1&&limit<=50&&query.length()<=100,"分页或查询参数无效");String from=" FROM a_agent_tool_logs l JOIN a_agent_turns t ON t.turn_id=l.turn_id JOIN a_agent_conversations c ON c.conversation_id=t.conversation_id WHERE c.scope_code=? AND c.data_mode=? AND c.owner_user=? AND c.client_type='admin' AND l.tool_name LIKE ? ESCAPE '!'";String keyword="%"+EhrService.like(query)+"%";long total=db.count("SELECT COUNT(*)"+from,a.scope,a.mode,a.user,keyword);return ok(map("total",total,"items",db.all("SELECT l.tool_log_id id,l.tool_name `function`,l.outcome,l.duration_ms durationMs,l.created_at createdAt"+from+" ORDER BY l.created_at DESC,l.tool_log_id DESC LIMIT ? OFFSET ?",a.scope,a.mode,a.user,keyword,limit,(page-1)*limit),"source","当前账号数字健康师真实工具调用日志；不含参数和职工资料"));}
}
